/**
 * Day 7 — Linked List and Arrays. Original statements + reference solutions
 * for the in-portal Striver SDE Sheet. Expected outputs are generated by verify.
 */

export default {
  section: 'Day 7: Linked List and Arrays',
  problems: [
    {
      slug: 'rotate-linked-list',
      title: 'Rotate a Linked List',
      difficulty: 'Medium',
      topic: 'Linked Lists',
      description: `Given a linked list of \`N\` nodes, rotate it to the **right** by \`k\` positions: the last \`k\` nodes move to the front. If \`k\` is larger than \`N\`, it wraps around.

Input format: first line has \`N k\`, second line the \`N\` node values.

Print the list after rotation, separated by single spaces.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n0 <= k <= 10^9\n-10^9 <= node value <= 10^9',
      inputs: [
        '5 2\n1 2 3 4 5',
        '1 5\n7',
        '3 0\n1 2 3',
        '4 4\n1 2 3 4',
        '6 15\n10 20 30 40 50 60',
        '2 1\n9 8',
        '7 3\n1 2 3 4 5 6 7',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const [N, k] = lines[0].split(/\s+/).map(Number);
        const arr = lines[1].split(/\s+/).slice(0, N);
        const shift = k % N;
        if (shift === 0) return arr.join(' ');
        return [...arr.slice(N - shift), ...arr.slice(0, N - shift)].join(' ');
      },
    },
    {
      slug: 'clone-list-random-pointer',
      title: 'Clone a Linked List with Random Pointer',
      difficulty: 'Medium',
      topic: 'Linked Lists',
      description: `Every node of a linked list has two pointers: \`next\` (to the following node) and \`random\` (to any node in the list, or nowhere).

Build a **deep copy** of the list: a brand-new list where each node's \`next\` and \`random\` point inside the new list exactly the same way as in the original.

Input format: first line \`N\`, then \`N\` lines each containing \`value randomIndex\` (0-based, \`-1\` when \`random\` points nowhere), head first.

Print \`N\` lines: for each node of the copy, its value followed by the **value** of the node its \`random\` pointer targets (\`-1\` if it points nowhere).

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n-10^9 <= value <= 10^9\n-1 <= randomIndex < N',
      inputs: [
        '3\n7 2\n13 0\n11 -1',
        '1\n5 -1',
        '4\n1 -1\n2 3\n3 1\n4 0',
        '5\n10 1\n20 2\n30 3\n40 4\n50 0',
        '2\n1 1\n2 0',
        '6\n1 5\n2 3\n3 3\n4 -1\n5 1\n6 0',
        '4\n9 0\n8 1\n7 2\n6 3',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const N = Number(lines[0]);
        const nodes = [];
        for (let i = 1; i <= N; i++) nodes.push(lines[i].split(/\s+/).map(Number));
        return nodes
          .map(([value, random]) => `${value} ${random === -1 ? -1 : nodes[random][0]}`)
          .join('\n');
      },
    },
    {
      slug: 'three-sum',
      title: '3Sum (count distinct triplets)',
      difficulty: 'Medium',
      topic: 'Two Pointers',
      description: `Given an array of \`N\` integers, count the number of **distinct value triplets** \`(a, b, c)\` with \`a + b + c = 0\` taken from three different positions \`i < j < k\`.

Triplets with the same three values count only once.

Input format: first line \`N\`, second line the \`N\` integers.

Print the number of distinct triplets.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 2000\n-10^5 <= arr[i] <= 10^5',
      inputs: [
        '6\n-1 0 1 2 -1 -4',
        '3\n0 0 0',
        '1\n5',
        '4\n0 0 0 0',
        '5\n-2 0 1 1 2',
        '7\n-1 -1 -1 0 0 0 1',
        '6\n1 2 -2 -1 -3 3',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const arr = lines[1].split(/\s+/).map(Number).sort((a, b) => a - b);
        const seen = new Set();
        let count = 0;
        for (let i = 0; i < arr.length - 2; i++) {
          let lo = i + 1, hi = arr.length - 1;
          while (lo < hi) {
            const sum = arr[i] + arr[lo] + arr[hi];
            if (sum === 0) {
              const key = `${arr[i]},${arr[lo]},${arr[hi]}`;
              if (!seen.has(key)) { seen.add(key); count++; }
              lo++; hi--;
            } else if (sum < 0) lo++;
            else hi--;
          }
        }
        return String(count);
      },
    },
    {
      slug: 'trapping-rainwater',
      title: 'Trapping Rain Water',
      difficulty: 'Hard',
      topic: 'Two Pointers',
      description: `Given \`N\` non-negative integers representing an elevation map where each bar has width 1, compute how much water it can trap after raining.

Input format: first line \`N\`, second line the \`N\` heights.

Print the total units of trapped water.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n0 <= height[i] <= 10^5',
      inputs: [
        '12\n0 1 0 2 1 0 1 3 2 1 2 1',
        '6\n4 2 0 3 2 5',
        '1\n7',
        '2\n5 5',
        '5\n1 2 3 4 5',
        '7\n3 0 0 2 0 4 0',
        '8\n5 5 5 0 0 5 5 5',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const h = lines[1].split(/\s+/).map(Number);
        let left = 0, right = h.length - 1, leftMax = 0, rightMax = 0, water = 0;
        while (left <= right) {
          if (h[left] <= h[right]) {
            leftMax = Math.max(leftMax, h[left]);
            water += leftMax - h[left];
            left++;
          } else {
            rightMax = Math.max(rightMax, h[right]);
            water += rightMax - h[right];
            right--;
          }
        }
        return String(water);
      },
    },
    {
      slug: 'remove-duplicates-sorted-array',
      title: 'Remove Duplicates from Sorted Array',
      difficulty: 'Easy',
      topic: 'Two Pointers',
      description: `Given a sorted array of \`N\` integers (possibly with duplicates), remove the duplicates in place so every value appears exactly once, keeping the original relative order.

Input format: first line \`N\`, second line the \`N\` integers (sorted non-decreasing).

Print the array after removing duplicates.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\n-10^9 <= arr[i] <= 10^9',
      inputs: [
        '8\n0 0 1 1 1 2 2 3',
        '1\n5',
        '5\n1 1 2 2 3',
        '6\n-3 -3 -1 0 0 4',
        '4\n1 2 3 4',
        '9\n1 1 1 1 1 1 1 1 2',
        '5\n2 2 2 2 2',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const arr = lines[1].split(/\s+/).map(Number);
        const unique = [];
        for (const x of arr) {
          if (!unique.length || unique[unique.length - 1] !== x) unique.push(x);
        }
        return unique.join(' ');
      },
    },
    {
      slug: 'max-consecutive-ones',
      title: 'Max Consecutive Ones',
      difficulty: 'Easy',
      topic: 'Arrays',
      description: `Given a binary array of \`N\` values (\`0\`s and \`1\`s), find the length of the longest contiguous run of \`1\`s.

Input format: first line \`N\`, second line the \`N\` values.

Print the length of the longest run of \`1\`s.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 10^5\narr[i] is 0 or 1',
      inputs: [
        '8\n1 1 0 1 1 1',
        '1\n0',
        '5\n1 1 1 1 1',
        '9\n0 0 0 0 0 0 0 0 0',
        '7\n1 0 1 0 1 0 1',
        '10\n1 1 1 0 1 1 1 1 0 1',
        '6\n0 1 1 1 1 0',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const arr = lines[1].split(/\s+/).map(Number);
        let best = 0, cur = 0;
        for (const x of arr) {
          cur = x === 1 ? cur + 1 : 0;
          best = Math.max(best, cur);
        }
        return String(best);
      },
    },
  ],
};